Cho $\triangle {ACE}$, vẽ điểm ${M}$ là trung điểm của ${CE}$. Trên tia đối của tia ${MA}$ lấy điểm ${J}$ sao cho ${MA = MJ}$. Xét tính đúng-sai của các khẳng định sau. 

\choiceTF
{ \True  $\triangle {ACM} = \triangle {JEM}$ }
   { $\widehat{A C M}=\widehat{E J M}$   }
     { \True  ${AC \parallel JE}$ }
    { \True Kẻ ${CK \perp AM}$ (${K \in AM}$), ${EL \perp JM}$ ($L \in JM$). Khi đó ${M}$ là trung điểm của ${KL}$  }
}{
\begin{tikzpicture}[scale=1, font=\footnotesize, line join=round, line cap=round, >=stealth]
    \def\r{2.5}

    \def\gocA{130}
    \path (0,0) coordinate (O)
    (\gocA:\r) coordinate (A)
    (210:\r) coordinate (B)
    (-30:\r) coordinate (C)
    ($(C)!0.5!(B)$) coordinate (M)
    ($(A)!2!(M)$) coordinate (D)
    ($(A)!(B)!(M)$) coordinate (E) 
    ($(A)!(C)!(M)$) coordinate (F) 
    ;
    \draw (A)--(B)--(C)--cycle (C)--(D)--(A)  (B)--(E)  (C)--(F)
    ;
    \foreach \x/\y in {M/B,M/C}{
        \draw ($(\x)!0.5!(\y)!4pt!90:(\x)$)--($(\x)!0.5!(\y)!4pt!-90:(\x)$);}
    \foreach \x/\y/\z in{B/E/A,C/F/D}
    \path pic[draw=black,angle radius = 6] {right angle = \x--\y--\z} ; 
    \filldraw[black] (A) circle (2pt) node[above left ] {$A$};
    \filldraw[black] (B) circle (2pt) node[below left] {$C$};
    \filldraw[black] (C) circle (2pt) node[above ] {$E$};
   \filldraw[black] (D) circle (2pt) node[below]{$J$};
     \filldraw[black] (E) circle (2pt) node[above right ] {$K$};
    \filldraw[black] (F) circle (2pt) node[below left] {$L$};

